def main():
 summary=list(csv.DictReader((ROOT/'evaluation/summary.csv').open()));stats=json.loads((ROOT/'evaluation/paired_statistics.json').read_text())['results'];budget=json.loads((ROOT/'budget.json').read_text());fold=json.loads((ROOT/'evaluation/folding_check.json').read_text());lines=['# 单个联合参考系编辑器 v1', (ROOT/'FINDINGS.md').read_text() if (ROOT/'FINDINGS.md').exists() else '结果分析尚未完成。', '## 新共同确认集：主结果','每层80个独立新世界；所有方法相同源、联合目标。联合/折叠一次应用只有终点，不能赋予虚构的两步轨迹。','|方法|层|参数|终点joint|完整轨迹（仅顺序）|日期正确|人称正确|非日期事实确认保持|已解析非日期错误|未决|正常结束|','|---|---|---:|---|---|---|---|---|---:|---:|---|']
 for r in summary:
  m=r['method'];params=76032 if m=='Joint16' else 152064 if m.startswith('Sequential') else 149760
  def rate(k):return f"{r[k]}/80 ({int(r[k])/80*100:.2f}%)"
  lines.append('|'+m+'|'+r['split']+'|'+str(params)+'|'+rate('endpoint_joint')+'|'+(rate('trajectory_joint') if r['trajectory_joint']!='' else 'N/A')+'|'+rate('date_ok')+'|'+rate('person_ok')+'|'+rate('nondate_ok')+'|'+r['confirmed_nondate_error']+'|'+r['unresolved']+'|'+rate('normal_end')+'|')
 lines += ['\n两个顺序的gold终点逐条相同。模型输出不要求交换；两者分别计分。错误日期与非日期字段分开，未决保留全部80分母、不自动等于已证实语义错误。数量、作者/角色、动作、对象、记录日期、状态、否定及归属的逐阶段判定和分母见field_scores.csv；状态/偏移/否定分层见stratified.csv。', '## 配对差值','主指标为终点joint，2000次world配对bootstrap；同世界所有方法使用相同重采样。只有seed42，区间不包括训练随机性；这些是探索性比较。','|层|比较|差值百分点|95%记录bootstrap区间|胜/负世界数|','|---|---|---:|---|---|']
 for r in stats:lines.append(f"|{r['split']}|{r['method_a']} − {r['method_b']}|{100*r['difference']:+.2f}|[{100*r['ci95'][0]:+.2f}, {100*r['ci95'][1]:+.2f}]|{r['wins']}/{r['losses']}|")
 lines += ['## 无训练仿射折叠','折叠参数149760，与Joint32相同；它只改写旧G1函数，没有联合监督。原两个独立编辑器活动参数152064，旧四算子组总参数304128。','|顺序|N|最大绝对误差|最大相对L2|文本/EOS完全一致|token IDs完全一致|终点判定一致|','|---|---:|---:|---:|---|---|---|']
 for r in fold:lines.append(f"|{r['order']}|160|{r['max_abs']:.9g}|{r['max_relative_l2']:.9g}|{r['exact_text_and_end']}/160|{r['exact_token_ids']}/160|{r['endpoint_decision_equal']}/160|")
 lines += ['这些数值只检验仿射实现等价，不解释为语义距离或机制证据。原padding全部保持，原纯表示序列的mask没有换成生成句子的mask。', '## 数据、训练与监督预算','train/dev复用480/80世界，联合合法视图1600/266。两组同一9600出现的日程，每世界20次，枚举合法偏移并按epoch轮换；相同world/source/target/token监督，不进行rank/LR搜索。新IID/OOD各80完整事实键与旧所有集合去重。OOD仍是原模板家族，词汇共享。', '每组600更新、有效batch16/micro4，AdamW .001、weight_decay0、clip1、float32，无调度。外层损失按有效目标token聚合；只监督一次联合终点。每100完整联合dev token NLL选best，平局较早。旧G1权重不训练。', '|方法|更新/选中步|best联合dev NLL|监督样本|有效监督token|算子样本调用|decoder前向batch|训练含dev秒|峰值CUDA分配字节|','|---|---|---:|---:|---:|---:|---:|---:|---:|']
 for rank in [16,32]:
  c=json.loads((ROOT/f'checkpoints/Joint{rank}/complete.json').read_text());lines.append(f"|Joint{rank}|600/{c['beststep']}|{c['best_dev_nll']:.8g}|{c['supervised_samples']}|{c['supervision_tokens']}|{c['operator_sample_calls']}|{c['decoder_forward_batches']}|{c['wall_seconds']:.2f}|{c['peak_cuda_bytes']}|")
 old=json.loads((CROSS/f'checkpoints/{NAME}/G1/complete.json').read_text());lines += [f"旧G1总训练样本9600，有效监督token {sum(v['supervision_tokens'] for v in old['counts'].values())}，分配给四个独立任务。本轮每组9600样本全为联合目标，因此不称严格等任务监督、等参数或等FLOPs。新rank32与折叠rank32参数相同，但训练来源不同；优势不能唯一归因于调用次数或容量。",'## 对照与可信度']
 for r in csv.DictReader((ROOT/'evaluation/controls.csv').open()):lines.append(f"{r['split']} / {r['role']}无编辑重构：{r['joint_ok']}/{r['N']}。")
 rules=read('outputs/rules.jsonl');lines += [f"源文本规则基线：{sum(all(s['score']['joint_ok'] for st in r['orders'].values() for s in st) for r in rules)}/160世界的两种规则路径均正确。规则只读取源及frame；目标重构仅为oracle可重构性诊断。",'GPU预检32条G1存档路径逐字复现，复用校准400个源/目标视图均正确。真实batch确认骨干冻结无梯度、H和活动低秩因子梯度有限非零，非零残差仍保持padding；首步V梯度为0符合零U初始化。详见calibration/interface_check.json和EVIDENCE_AUDIT.md。', '## GPU账本与交付',f"累计{budget['total_gpu_seconds']} GPU分配秒（{budget['total_gpu_seconds']/3600:.4f}小时），上限7200；sbatch+srun，每作业1卡、峰值2卡。父/step取最大ElapsedRaw，不重复累计；队列另列，加载/预检/训练/dev/确认均计入。没有新增模型或seed。",'timing.csv分别记录encode、edit、终点decode与顺序链的诊断decode，后者不算实际纯链执行所必需。单次测量和监督量不同，不宣称端到端加速。','完整原始输出在outputs/，训练曲线与checkpoint在checkpoints/。预选20世界的可读配对案例：[review/CASES.md](review/CASES.md)；匿名CSV和独立方法映射亦保存。尚无真人审核；结构化自动检查加便利模型复核不等于人类真值。','模型和tokenizer revision、环境、初始化、日程、数据、checkpoint与代码hash已保存，旧资产核验不变。可复现命令见README.md和commands.log。基础模型及latest.pt优化器/RNG恢复状态仅保留本地，远端只推独立分支。']
 (ROOT/'REPORT.md').write_text(''.join(('\n' if i and s.startswith('|') and lines[i-1].startswith('|') else '\n\n' if i else '')+s for i,s in enumerate(lines))+'\n');print('report written')
if __name__=='__main__':main()
